echo "Removing $HOME/Library/HTTPStorages/net.freemacsoft.AppCleaner..."
if [ -d "$HOME/Library/HTTPStorages/net.freemacsoft.AppCleaner" ]; then
    rm -rf "$HOME/Library/HTTPStorages/net.freemacsoft.AppCleaner" 2>/dev/null || true
elif [ -f "$HOME/Library/HTTPStorages/net.freemacsoft.AppCleaner" ]; then
    rm -f "$HOME/Library/HTTPStorages/net.freemacsoft.AppCleaner" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/net.freemacsoft.AppCleaner-SmartDelete.plist
echo "Removing $HOME/Library/Preferences/net.freemacsoft.AppCleaner-SmartDelete.plist..."
