    rm -f "$HOME/Library/Preferences/net.freemacsoft.AppCleaner-SmartDelete.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/net.freemacsoft.AppCleaner.plist
echo "Removing $HOME/Library/Preferences/net.freemacsoft.AppCleaner.plist..."
if [ -d "$HOME/Library/Preferences/net.freemacsoft.AppCleaner.plist" ]; then
    rm -rf "$HOME/Library/Preferences/net.freemacsoft.AppCleaner.plist" 2>/dev/null || true
